SELECT country, credit_limit_bucket, unique_segments FROM (SELECT country, CASE WHEN credit_limit >= 16300 THEN 'high' WHEN credit_limit >= 6400 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, COUNT(DISTINCT age) AS unique_segments FROM customers GROUP BY country, CASE WHEN credit_limit >= 16300 THEN 'high' WHEN credit_limit >= 6400 THEN 'mid' ELSE 'low' END) AS t WHERE unique_segments < 4 ORDER BY unique_segments DESC
